import React, { useState } from "react";
import { Outlet, Link, useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import { useTheme } from "../contexts/ThemeContext";
import {
  HomeIcon,
  UserIcon,
  Bars3Icon,
  XMarkIcon,
  SunIcon,
  MoonIcon,
  ComputerDesktopIcon,
  ArrowRightOnRectangleIcon,
  BuildingStorefrontIcon,
  DocumentTextIcon,
  AcademicCapIcon,
  ShieldCheckIcon,
  TruckIcon,
  WrenchScrewdriverIcon,
  ClipboardDocumentCheckIcon,
} from "@heroicons/react/24/outline";

const DashboardLayout: React.FC = () => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const { user, logout } = useAuth();
  const { theme, setTheme, resolvedTheme } = useTheme();
  const location = useLocation();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  const navigation = [
    { name: "Dashboard", href: "/dashboard", icon: HomeIcon },
    { name: "Profile", href: "/profile", icon: UserIcon },
  ];

  // ERP Navigation
  const erpNavigation = [
    {
      name: "Manufacturing",
      href: "/erp/manufacturing",
      icon: WrenchScrewdriverIcon,
    },
    { name: "Quality", href: "/erp/quality", icon: ClipboardDocumentCheckIcon },
    { name: "Inventory", href: "/erp/inventory", icon: BuildingStorefrontIcon },
    { name: "Supply Chain", href: "/erp/supply-chain", icon: TruckIcon },
  ];

  // RDS Navigation
  const rdsNavigation = [
    { name: "Documents", href: "/rds/documents", icon: DocumentTextIcon },
    { name: "Compliance", href: "/rds/compliance", icon: ShieldCheckIcon },
  ];

  // LMS Navigation
  const lmsNavigation = [
    { name: "Training", href: "/lms/training", icon: AcademicCapIcon },
    {
      name: "Certifications",
      href: "/lms/certifications",
      icon: ShieldCheckIcon,
    },
  ];

  // Regulatory Navigation
  const regulatoryNavigation = [
    { name: "Dashboard", href: "/regulatory/dashboard", icon: HomeIcon },
    { name: "Audit Trail", href: "/regulatory/audit", icon: DocumentTextIcon },
  ];

  const isActive = (href: string) => {
    return location.pathname === href;
  };

  const NavItem = ({ item }: { item: (typeof navigation)[0] }) => (
    <Link
      to={item.href}
      className={`group flex items-center px-2 py-2 text-sm font-medium rounded-md transition-colors ${
        isActive(item.href)
          ? "bg-blue-100 text-blue-900 dark:bg-blue-900 dark:text-blue-100"
          : "text-gray-600 hover:bg-gray-50 hover:text-gray-900 dark:text-gray-300 dark:hover:bg-gray-700 dark:hover:text-white"
      }`}
    >
      <item.icon
        className={`mr-3 h-5 w-5 flex-shrink-0 ${
          isActive(item.href)
            ? "text-blue-500 dark:text-blue-300"
            : "text-gray-400 group-hover:text-gray-500 dark:group-hover:text-gray-300"
        }`}
      />
      {item.name}
    </Link>
  );

  const NavSection = ({
    title,
    items,
  }: {
    title: string;
    items: typeof navigation;
  }) => (
    <div>
      <h3 className="px-3 text-xs font-semibold text-gray-500 uppercase tracking-wider dark:text-gray-400">
        {title}
      </h3>
      <div className="mt-1 space-y-1">
        {items.map((item) => (
          <NavItem key={item.name} item={item} />
        ))}
      </div>
    </div>
  );

  return (
    <div className="h-screen flex overflow-hidden bg-gray-100 dark:bg-gray-900">
      {/* Mobile sidebar */}
      <div
        className={`fixed inset-0 flex z-40 md:hidden ${
          sidebarOpen ? "" : "hidden"
        }`}
      >
        <div
          className="fixed inset-0 bg-gray-600 bg-opacity-75"
          onClick={() => setSidebarOpen(false)}
        />
        <div className="relative flex-1 flex flex-col max-w-xs w-full bg-white dark:bg-gray-800">
          <div className="absolute top-0 right-0 -mr-12 pt-2">
            <button
              type="button"
              className="ml-1 flex items-center justify-center h-10 w-10 rounded-full focus:outline-none focus:ring-2 focus:ring-inset focus:ring-white"
              onClick={() => setSidebarOpen(false)}
            >
              <XMarkIcon className="h-6 w-6 text-white" />
            </button>
          </div>
          <SidebarContent />
        </div>
      </div>

      {/* Static sidebar for desktop */}
      <div className="hidden md:flex md:flex-shrink-0">
        <div className="flex flex-col w-64">
          <div className="flex flex-col h-0 flex-1 border-r border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800">
            <SidebarContent />
          </div>
        </div>
      </div>

      {/* Main content */}
      <div className="flex flex-col w-0 flex-1 overflow-hidden">
        <div className="relative z-10 flex-shrink-0 flex h-16 bg-white dark:bg-gray-800 shadow">
          <button
            type="button"
            className="px-4 border-r border-gray-200 dark:border-gray-700 text-gray-500 focus:outline-none focus:ring-2 focus:ring-inset focus:ring-blue-500 md:hidden"
            onClick={() => setSidebarOpen(true)}
          >
            <Bars3Icon className="h-6 w-6" />
          </button>
          <div className="flex-1 px-4 flex justify-between">
            <div className="flex-1 flex">
              <div className="w-full flex md:ml-0">
                <label htmlFor="search-field" className="sr-only">
                  Search
                </label>
                <div className="relative w-full text-gray-400 focus-within:text-gray-600 dark:focus-within:text-gray-300">
                  <div className="absolute inset-y-0 left-0 flex items-center pointer-events-none">
                    <svg
                      className="h-5 w-5"
                      fill="currentColor"
                      viewBox="0 0 20 20"
                    >
                      <path
                        fillRule="evenodd"
                        d="M8 4a4 4 0 100 8 4 4 0 000-8zM2 8a6 6 0 1110.89 3.476l4.817 4.817a1 1 0 01-1.414 1.414l-4.816-4.816A6 6 0 012 8z"
                        clipRule="evenodd"
                      />
                    </svg>
                  </div>
                  <input
                    id="search-field"
                    className="block w-full h-full pl-8 pr-3 py-2 border-transparent text-gray-900 dark:text-white placeholder-gray-500 dark:placeholder-gray-400 focus:outline-none focus:placeholder-gray-400 focus:ring-0 focus:border-transparent sm:text-sm bg-transparent"
                    placeholder="Search..."
                    type="search"
                    name="search"
                  />
                </div>
              </div>
            </div>
            <div className="ml-4 flex items-center md:ml-6">
              {/* Theme selector */}
              <div className="relative">
                <button
                  type="button"
                  className="p-1 rounded-full text-gray-400 hover:text-gray-500 dark:hover:text-gray-300 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                  onClick={() => {
                    const themes: ("light" | "dark" | "system")[] = [
                      "light",
                      "dark",
                      "system",
                    ];
                    const currentIndex = themes.indexOf(theme);
                    const nextIndex = (currentIndex + 1) % themes.length;
                    setTheme(themes[nextIndex]);
                  }}
                >
                  {resolvedTheme === "dark" ? (
                    <MoonIcon className="h-6 w-6" />
                  ) : resolvedTheme === "light" ? (
                    <SunIcon className="h-6 w-6" />
                  ) : (
                    <ComputerDesktopIcon className="h-6 w-6" />
                  )}
                </button>
              </div>

              {/* Profile dropdown */}
              <div className="ml-3 relative">
                <div className="flex items-center">
                  <button
                    type="button"
                    className="max-w-xs bg-white dark:bg-gray-800 flex items-center text-sm rounded-full focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
                    onClick={handleLogout}
                  >
                    <span className="sr-only">Open user menu</span>
                    <div className="flex items-center">
                      <div className="flex-shrink-0 h-8 w-8">
                        <div className="h-8 w-8 rounded-full bg-blue-500 flex items-center justify-center">
                          <span className="text-sm font-medium text-white">
                            {user?.firstName?.[0]}
                            {user?.lastName?.[0]}
                          </span>
                        </div>
                      </div>
                      <span className="ml-3 text-gray-700 dark:text-gray-300 text-sm font-medium">
                        {user?.firstName} {user?.lastName}
                      </span>
                      <ArrowRightOnRectangleIcon className="ml-2 h-5 w-5 text-gray-400" />
                    </div>
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>

        <main className="flex-1 relative overflow-y-auto focus:outline-none">
          <div className="py-6">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 md:px-8">
              <Outlet />
            </div>
          </div>
        </main>
      </div>
    </div>
  );

  function SidebarContent() {
    return (
      <div className="flex-1 flex flex-col pt-5 pb-4 overflow-y-auto">
        <div className="flex items-center flex-shrink-0 px-4">
          <h1 className="text-xl font-bold text-gray-900 dark:text-white">
            Radix Labs ERP
          </h1>
        </div>
        <nav className="mt-5 flex-1 px-2 space-y-8">
          <NavSection title="General" items={navigation} />
          <NavSection title="ERP" items={erpNavigation} />
          <NavSection title="Regulatory Docs" items={rdsNavigation} />
          <NavSection title="Learning" items={lmsNavigation} />
          <NavSection title="Regulatory" items={regulatoryNavigation} />
        </nav>
      </div>
    );
  }
};

export default DashboardLayout;
