import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
} from "react-router-dom";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { Toaster } from "react-hot-toast";
import { AuthProvider } from "./contexts/AuthContext";
import { SocketProvider } from "./contexts/SocketContext";
import { ThemeProvider } from "./contexts/ThemeContext";

// Layouts
import AuthLayout from "./layouts/AuthLayout";
import DashboardLayout from "./layouts/DashboardLayout";

// Pages
import Login from "./pages/auth/Login";
import Register from "./pages/auth/Register";
import Dashboard from "./pages/dashboard/Dashboard";
import Profile from "./pages/profile/Profile";

// ERP Pages
import Manufacturing from "./pages/erp/Manufacturing";
import Quality from "./pages/erp/Quality";
import Inventory from "./pages/erp/Inventory";
import SupplyChain from "./pages/erp/SupplyChain";

// RDS Pages
import DocumentManagement from "./pages/rds/DocumentManagement";
import ComplianceEngine from "./pages/rds/ComplianceEngine";

// LMS Pages
import TrainingModules from "./pages/lms/TrainingModules";
import Certifications from "./pages/lms/Certifications";

// Regulatory Pages
import ComplianceDashboard from "./pages/regulatory/ComplianceDashboard";
import AuditTrail from "./pages/regulatory/AuditTrail";

// Protected Route Component
import ProtectedRoute from "./components/auth/ProtectedRoute";

// Styles
import "./styles/globals.css";

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      refetchOnWindowFocus: false,
      staleTime: 5 * 60 * 1000, // 5 minutes
    },
  },
});

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <ThemeProvider>
        <AuthProvider>
          <SocketProvider>
            <Router>
              <div className="min-h-screen bg-gray-50 dark:bg-gray-900">
                <Routes>
                  {/* Public Routes */}
                  <Route path="/" element={<AuthLayout />}>
                    <Route index element={<Navigate to="/login" replace />} />
                    <Route path="login" element={<Login />} />
                    <Route path="register" element={<Register />} />
                  </Route>

                  {/* Protected Routes */}
                  <Route
                    path="/"
                    element={
                      <ProtectedRoute>
                        <DashboardLayout />
                      </ProtectedRoute>
                    }
                  >
                    <Route path="dashboard" element={<Dashboard />} />
                    <Route path="profile" element={<Profile />} />

                    {/* ERP Routes */}
                    <Route
                      path="erp/manufacturing"
                      element={<Manufacturing />}
                    />
                    <Route path="erp/quality" element={<Quality />} />
                    <Route path="erp/inventory" element={<Inventory />} />
                    <Route path="erp/supply-chain" element={<SupplyChain />} />

                    {/* RDS Routes */}
                    <Route
                      path="rds/documents"
                      element={<DocumentManagement />}
                    />
                    <Route
                      path="rds/compliance"
                      element={<ComplianceEngine />}
                    />

                    {/* LMS Routes */}
                    <Route path="lms/training" element={<TrainingModules />} />
                    <Route
                      path="lms/certifications"
                      element={<Certifications />}
                    />

                    {/* Regulatory Routes */}
                    <Route
                      path="regulatory/dashboard"
                      element={<ComplianceDashboard />}
                    />
                    <Route path="regulatory/audit" element={<AuditTrail />} />
                  </Route>

                  {/* Catch all route */}
                  <Route
                    path="*"
                    element={<Navigate to="/dashboard" replace />}
                  />
                </Routes>
              </div>
            </Router>

            {/* Toast notifications */}
            <Toaster
              position="top-right"
              toastOptions={{
                duration: 4000,
                style: {
                  background: "#363636",
                  color: "#fff",
                },
              }}
            />
          </SocketProvider>
        </AuthProvider>
      </ThemeProvider>
    </QueryClientProvider>
  );
}

export default App;
