/**
 * API Configuration Utility
 * Handles API URL resolution for both web and Electron contexts
 */

export const getApiBaseUrl = (): string => {
  // Check if running in Electron
  if (typeof window !== "undefined" && (window as any).electronAPI) {
    // Running in Electron - use fixed backend URL
    return "http://localhost:3001";
  }

  // Development/Production: use relative URLs (works with proxy and deployed apps)
  return "";
};

/**
 * Make an API request with proper URL handling
 */
export const apiRequest = async (
  endpoint: string,
  options: RequestInit = {}
): Promise<Response> => {
  const baseUrl = getApiBaseUrl();
  const url = `${baseUrl}${endpoint}`;

  return fetch(url, options);
};
